	unresolved := false

	evalPrimitive := func(expr string) (bool, error) {
		expr = strings.TrimSpace(expr)
		if expr == "" {
			return false, fmt.Errorf("invalid condition: empty expression")
		}

		substitute := func(s string) (string, bool) {
			res, err := substituteVariables(strings.TrimSpace(s), vars)
